import{_ as a,o as r,c as d,ag as o}from"./chunks/framework.i8sMDeRW.js";const u=JSON.parse('{"title":"PRD: [产品名称]","description":"","frontmatter":{},"headers":[],"relativePath":"guide/02-prd/ai-saas-prd-template.md","filePath":"guide/02-prd/ai-saas-prd-template.md","lastUpdated":1778766569000}'),e={name:"guide/02-prd/ai-saas-prd-template.md"};function l(h,t,n,i,s,b){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="prd-产品名称" tabindex="-1">PRD: [产品名称] <a class="header-anchor" href="#prd-产品名称" aria-label="Permalink to &quot;PRD: [产品名称]&quot;">​</a></h1><table tabindex="0"><thead><tr><th>元数据</th><th>内容</th></tr></thead><tbody><tr><td><strong>文档状态</strong></td><td>[草稿 / 评审中 / 已定稿]</td></tr><tr><td><strong>版本号</strong></td><td>v[0.1.0]</td></tr><tr><td><strong>作者</strong></td><td>[姓名]</td></tr><tr><td><strong>创建日期</strong></td><td>[YYYY-MM-DD]</td></tr><tr><td><strong>最后更新</strong></td><td>[YYYY-MM-DD]</td></tr></tbody></table><hr><h2 id="_1-产品概述" tabindex="-1">1. 产品概述 <a class="header-anchor" href="#_1-产品概述" aria-label="Permalink to &quot;1. 产品概述&quot;">​</a></h2><h3 id="_1-1-定位与愿景" tabindex="-1">1.1 定位与愿景 <a class="header-anchor" href="#_1-1-定位与愿景" aria-label="Permalink to &quot;1.1 定位与愿景&quot;">​</a></h3><p>[用 3-5 句话描述产品定位。例如：本产品是一个面向[目标用户]的 AI SaaS 平台，通过调用[基础模型]实现[核心功能]，帮助用户在[使用场景]中提升效率。]</p><h3 id="_1-2-目标用户" tabindex="-1">1.2 目标用户 <a class="header-anchor" href="#_1-2-目标用户" aria-label="Permalink to &quot;1.2 目标用户&quot;">​</a></h3><ul><li><strong>主要用户</strong>：[如：中小企业的产品经理、运营人员]</li><li><strong>次要用户</strong>：[如：开发者、数据分析师]</li><li><strong>决策者</strong>：[如：CTO、产品总监]</li></ul><h3 id="_1-3-用户痛点" tabindex="-1">1.3 用户痛点 <a class="header-anchor" href="#_1-3-用户痛点" aria-label="Permalink to &quot;1.3 用户痛点&quot;">​</a></h3><ol><li>[痛点 1：例如现有工具缺乏智能辅助，手动操作耗时]</li><li>[痛点 2：例如跨平台数据无法打通]</li><li>[痛点 3：例如推理响应慢，影响用户体验]</li></ol><h3 id="_1-4-成功指标-okr" tabindex="-1">1.4 成功指标 (OKR) <a class="header-anchor" href="#_1-4-成功指标-okr" aria-label="Permalink to &quot;1.4 成功指标 (OKR)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>目标值</th><th>测量方式</th></tr></thead><tbody><tr><td><strong>[指标 1]</strong></td><td>[如：日活用户 ≥ X]</td><td>[如：企业后台统计]</td></tr><tr><td><strong>[指标 2]</strong></td><td>[如：用户留存率 ≥ X%]</td><td>[如：GA / Mixpanel]</td></tr><tr><td><strong>[指标 3]</strong></td><td>[如：TTC(端到端延迟) ≤ X ms]</td><td>[如：APM 监控]</td></tr><tr><td><strong>[指标 4]</strong></td><td>[如：API 调用成功率 ≥ 99.X%]</td><td>[如：日志分析]</td></tr></tbody></table><hr><h2 id="_2-核心功能需求" tabindex="-1">2. 核心功能需求 <a class="header-anchor" href="#_2-核心功能需求" aria-label="Permalink to &quot;2. 核心功能需求&quot;">​</a></h2><h3 id="_2-1-功能清单" tabindex="-1">2.1 功能清单 <a class="header-anchor" href="#_2-1-功能清单" aria-label="Permalink to &quot;2.1 功能清单&quot;">​</a></h3><h4 id="f1-功能名称" tabindex="-1">F1：[功能名称] <a class="header-anchor" href="#f1-功能名称" aria-label="Permalink to &quot;F1：[功能名称]&quot;">​</a></h4><ul><li><strong>优先级</strong>：P0 / P1 / P2</li><li><strong>描述</strong>：[详细描述功能行为]</li><li><strong>用户故事</strong>： <blockquote><p>作为[用户角色]，我希望[执行动作]，以便[获得价值]。</p></blockquote></li><li><strong>验收标准</strong>： <ol><li>[条件 1]</li><li>[条件 2]</li><li>[条件 3]</li></ol></li><li><strong>UI/UX 备注</strong>：[交互原型参考、设计稿链接]</li></ul><h4 id="f2-功能名称" tabindex="-1">F2：[功能名称] <a class="header-anchor" href="#f2-功能名称" aria-label="Permalink to &quot;F2：[功能名称]&quot;">​</a></h4><ul><li><strong>优先级</strong>：P0 / P1 / P2</li><li><strong>描述</strong>：[详细描述功能行为]</li><li><strong>用户故事</strong>： <blockquote><p>作为[用户角色]，我希望[执行动作]，以便[获得价值]。</p></blockquote></li><li><strong>验收标准</strong>： <ol><li>[条件 1]</li><li>[条件 2]</li><li>[条件 3]</li></ol></li></ul><hr><h2 id="_3-ai-模型选型策略" tabindex="-1">3. AI/模型选型策略 <a class="header-anchor" href="#_3-ai-模型选型策略" aria-label="Permalink to &quot;3. AI/模型选型策略&quot;">​</a></h2><h3 id="_3-1-模型选择矩阵" tabindex="-1">3.1 模型选择矩阵 <a class="header-anchor" href="#_3-1-模型选择矩阵" aria-label="Permalink to &quot;3.1 模型选择矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐模型</th><th>备选模型</th><th>选型理由</th></tr></thead><tbody><tr><td>[场景 1：如文本生成]</td><td>[如：GPT-4o / Claude 3.5]</td><td>[如：Gemini 2.0]</td><td>[如：推理质量最高、生态成熟]</td></tr><tr><td>[场景 2：如意图分类]</td><td>[如：微调后的 LLaMA 3 8B]</td><td>[如：BERT-base]</td><td>[如：低延迟、成本可控]</td></tr><tr><td>[场景 3：如图像理解]</td><td>[如：GPT-4V / Claude 3 Vision]</td><td>[如：Qwen-VL]</td><td>[如：多模态能力满足需求]</td></tr></tbody></table><h3 id="_3-2-模型部署方式" tabindex="-1">3.2 模型部署方式 <a class="header-anchor" href="#_3-2-模型部署方式" aria-label="Permalink to &quot;3.2 模型部署方式&quot;">​</a></h3><ul><li><strong>云端推理</strong>：[是/否]，提供商：[如：OpenAI API / Azure OpenAI / AWS Bedrock]</li><li><strong>私有化部署</strong>：[是/否]，部署方案：[如：vLLM + H100 集群 / Ollama]</li><li><strong>混合部署策略</strong>：[如：核心高敏场景走本地部署，非敏感场景走云端 API]</li></ul><h3 id="_3-3-推理成本预算" tabindex="-1">3.3 推理成本预算 <a class="header-anchor" href="#_3-3-推理成本预算" aria-label="Permalink to &quot;3.3 推理成本预算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>预估成本</th></tr></thead><tbody><tr><td><strong>单个请求平均 Token 消耗</strong></td><td>[如：Prompt: 2K tokens + Completion: 500 tokens]</td></tr><tr><td><strong>每月预估调用量</strong></td><td>[如：1,000,000 次]</td></tr><tr><td><strong>每月模型 API 费用</strong></td><td>[如：¥X,XXX]</td></tr><tr><td><strong>自建推理集群成本</strong></td><td>[如：¥X,XXX / GPU 月租]</td></tr><tr><td><strong>年度预算上限</strong></td><td>[如：¥XXX,XXX]</td></tr></tbody></table><h3 id="_3-4-延迟要求-sla" tabindex="-1">3.4 延迟要求 (SLA) <a class="header-anchor" href="#_3-4-延迟要求-sla" aria-label="Permalink to &quot;3.4 延迟要求 (SLA)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>P50 目标</th><th>P99 目标</th><th>监控指标</th></tr></thead><tbody><tr><td><strong>[场景 1]</strong></td><td>≤ [X] ms</td><td>≤ [Y] ms</td><td>[如：LLM TTFT、TPOT]</td></tr><tr><td><strong>[场景 2]</strong></td><td>≤ [X] ms</td><td>≤ [Y] ms</td><td>[如：E2E 响应时间]</td></tr><tr><td><strong>[场景 3]</strong></td><td>≤ [X] ms</td><td>≤ [Y] ms</td><td>[如：流式首字符延迟]</td></tr></tbody></table><blockquote><p><strong>优化手段</strong>：[如：KV Cache / Prompt Cache / Speculative Decoding / 量化 INT4]</p></blockquote><hr><h2 id="_4-数据隐私与安全" tabindex="-1">4. 数据隐私与安全 <a class="header-anchor" href="#_4-数据隐私与安全" aria-label="Permalink to &quot;4. 数据隐私与安全&quot;">​</a></h2><h3 id="_4-1-数据分类" tabindex="-1">4.1 数据分类 <a class="header-anchor" href="#_4-1-数据分类" aria-label="Permalink to &quot;4.1 数据分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据类别</th><th>示例</th><th>敏感等级</th><th>处理方式</th></tr></thead><tbody><tr><td><strong>[类 1]</strong></td><td>[如：用户输入文本]</td><td>[高/中/低]</td><td>[如：传输加密 + 静态度量加密]</td></tr><tr><td><strong>[类 2]</strong></td><td>[如：企业知识库文档]</td><td>[高/中/低]</td><td>[如：RBAC 权限控制]</td></tr></tbody></table><h3 id="_4-2-合规要求" tabindex="-1">4.2 合规要求 <a class="header-anchor" href="#_4-2-合规要求" aria-label="Permalink to &quot;4.2 合规要求&quot;">​</a></h3><ul><li>[x] <strong>数据不用于模型训练</strong>：在 API 调用中配置 [如：<code>privacy_mode=true</code>] 确保用户数据不进入训练集</li><li>[x] <strong>数据驻留</strong>：数据存储区域为 [如：中国大陆（阿里云）]，符合 [如：《个人信息保护法》]</li><li>[x] <strong>合规认证</strong>：目标认证 [如：SOC 2 / ISO 27001 / 等保三级]</li><li>[ ] <strong>数据脱敏</strong>：[描述脱敏策略，如：在 Prompt 中自动过滤手机号、身份证等 PII 信息]</li></ul><h3 id="_4-3-用户数据使用条款" tabindex="-1">4.3 用户数据使用条款 <a class="header-anchor" href="#_4-3-用户数据使用条款" aria-label="Permalink to &quot;4.3 用户数据使用条款&quot;">​</a></h3><ul><li>[条款 1：如用户数据仅用于本次对话的推理，不做持久化存储]</li><li>[条款 2：如企业用户可选择开启数据日志用于质量改进]</li><li>[条款 3：如用户可在控制台一键删除所有历史数据]</li></ul><hr><h2 id="_5-a-b-测试策略" tabindex="-1">5. A/B 测试策略 <a class="header-anchor" href="#_5-a-b-测试策略" aria-label="Permalink to &quot;5. A/B 测试策略&quot;">​</a></h2><h3 id="_5-1-测试计划" tabindex="-1">5.1 测试计划 <a class="header-anchor" href="#_5-1-测试计划" aria-label="Permalink to &quot;5.1 测试计划&quot;">​</a></h3><table tabindex="0"><thead><tr><th>实验名称</th><th>变量</th><th>对照组</th><th>实验组</th><th>样本量</th><th>时长</th></tr></thead><tbody><tr><td><strong>[实验 1]</strong></td><td>[如：模型版本]</td><td>[如：GPT-4o]</td><td>[如：GPT-4.1]</td><td>[如：5% 流量]</td><td>[如：2 周]</td></tr><tr><td><strong>[实验 2]</strong></td><td>[如：Prompt 模板]</td><td>[如：原始 Prompt]</td><td>[如：优化后 Prompt]</td><td>[如：10% 流量]</td><td>[如：1 周]</td></tr></tbody></table><h3 id="_5-2-评估指标" tabindex="-1">5.2 评估指标 <a class="header-anchor" href="#_5-2-评估指标" aria-label="Permalink to &quot;5.2 评估指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标类别</th><th>具体指标</th><th>最小可检测效应</th></tr></thead><tbody><tr><td><strong>质量</strong></td><td>[如：BLEU / ROUGE-L / 人工评分 4.0+]</td><td>[如：+5%]</td></tr><tr><td><strong>体验</strong></td><td>[如：用户满意度评分 (CSAT)]</td><td>[如：+0.2]</td></tr><tr><td><strong>商业</strong></td><td>[如：转化率 / 付费率]</td><td>[如：+3%]</td></tr><tr><td><strong>成本</strong></td><td>[如：单次成本 / Token 消耗]</td><td>[如：-10%]</td></tr></tbody></table><h3 id="_5-3-回滚机制" tabindex="-1">5.3 回滚机制 <a class="header-anchor" href="#_5-3-回滚机制" aria-label="Permalink to &quot;5.3 回滚机制&quot;">​</a></h3><ul><li>[条件 1：如实验组 P99 延迟超过基线 30%，自动回滚]</li><li>[条件 2：如错误率 &gt; 5%，自动回滚]</li><li>[条件 3：如负面用户反馈超过 X 条，人工评估是否回滚]</li></ul><hr><h2 id="_6-非功能需求" tabindex="-1">6. 非功能需求 <a class="header-anchor" href="#_6-非功能需求" aria-label="Permalink to &quot;6. 非功能需求&quot;">​</a></h2><h3 id="_6-1-性能" tabindex="-1">6.1 性能 <a class="header-anchor" href="#_6-1-性能" aria-label="Permalink to &quot;6.1 性能&quot;">​</a></h3><ul><li><strong>并发支持</strong>：支持 [X] 并发用户</li><li><strong>吞吐量</strong>：≥ [X] QPS (每秒查询数)</li><li><strong>可用性 SLA</strong>：≥ 99.[X]%</li></ul><h3 id="_6-2-可扩展性" tabindex="-1">6.2 可扩展性 <a class="header-anchor" href="#_6-2-可扩展性" aria-label="Permalink to &quot;6.2 可扩展性&quot;">​</a></h3><ul><li><strong>水平扩展</strong>：通过 [如：K8s HPA / 无服务器架构] 自动扩缩容</li><li><strong>模型升级</strong>：支持无缝切换模型版本，灰度发布</li></ul><h3 id="_6-3-可观测性" tabindex="-1">6.3 可观测性 <a class="header-anchor" href="#_6-3-可观测性" aria-label="Permalink to &quot;6.3 可观测性&quot;">​</a></h3><ul><li><strong>日志</strong>：[如：结构化日志 + ELK / Loki]</li><li><strong>监控</strong>：[如：Prometheus + Grafana 仪表盘]</li><li><strong>告警</strong>：[如：PagerDuty / 飞书机器人告警]</li></ul><h3 id="_6-4-成本控制" tabindex="-1">6.4 成本控制 <a class="header-anchor" href="#_6-4-成本控制" aria-label="Permalink to &quot;6.4 成本控制&quot;">​</a></h3><ul><li><strong>预算</strong>：月度 API 调用预算 ¥[X]，超预算 80% 触发告警</li><li><strong>优化</strong>：[如：使用 Batch API 降本 / 小模型兜底 / 缓存策略]</li></ul><hr><h2 id="_7-实施路线图" tabindex="-1">7. 实施路线图 <a class="header-anchor" href="#_7-实施路线图" aria-label="Permalink to &quot;7. 实施路线图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>里程碑</th><th>时间</th><th>交付物</th><th>负责人</th></tr></thead><tbody><tr><td><strong>M1：MVP</strong></td><td>YYYY-MM-DD</td><td>[如：核心功能的命令行 Demo]</td><td>[姓名]</td></tr><tr><td><strong>M2：内测</strong></td><td>YYYY-MM-DD</td><td>[如：Web 端 Beta 版本，支持 X 用户]</td><td>[姓名]</td></tr><tr><td><strong>M3：公测</strong></td><td>YYYY-MM-DD</td><td>[如：开放注册，支持 Y 场景]</td><td>[姓名]</td></tr><tr><td><strong>M4：GA</strong></td><td>YYYY-MM-DD</td><td>[如：正式商业化上线]</td><td>[姓名]</td></tr></tbody></table><hr><h2 id="_8-风险与缓解措施" tabindex="-1">8. 风险与缓解措施 <a class="header-anchor" href="#_8-风险与缓解措施" aria-label="Permalink to &quot;8. 风险与缓解措施&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>概率</th><th>影响</th><th>缓解措施</th></tr></thead><tbody><tr><td><strong>[风险 1：模型效果不达预期]</strong></td><td>[高/中/低]</td><td>[高/中/低]</td><td>[如：准备多模型备选方案，预留 Prompt 工程优化预算]</td></tr><tr><td><strong>[风险 2：推理成本超预算]</strong></td><td>[高/中/低]</td><td>[高/中/低]</td><td>[如：设置成本上限，引入缓存和模型蒸馏]</td></tr><tr><td><strong>[风险 3：数据合规风险]</strong></td><td>[高/中/低]</td><td>[高/中/低]</td><td>[如：聘请外部审计、前置法务评审]</td></tr></tbody></table><hr><h2 id="_9-附录" tabindex="-1">9. 附录 <a class="header-anchor" href="#_9-附录" aria-label="Permalink to &quot;9. 附录&quot;">​</a></h2><h3 id="_9-1-参考文档" tabindex="-1">9.1 参考文档 <a class="header-anchor" href="#_9-1-参考文档" aria-label="Permalink to &quot;9.1 参考文档&quot;">​</a></h3><ul><li>[相关文档 1 标题]：链接</li><li>[相关文档 2 标题]：链接</li></ul><h3 id="_9-2-术语表" tabindex="-1">9.2 术语表 <a class="header-anchor" href="#_9-2-术语表" aria-label="Permalink to &quot;9.2 术语表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>定义</th></tr></thead><tbody><tr><td><strong>[术语 1]</strong></td><td>[定义]</td></tr><tr><td><strong>[术语 2]</strong></td><td>[定义]</td></tr></tbody></table><h3 id="_9-3-变更日志" tabindex="-1">9.3 变更日志 <a class="header-anchor" href="#_9-3-变更日志" aria-label="Permalink to &quot;9.3 变更日志&quot;">​</a></h3><table tabindex="0"><thead><tr><th>版本</th><th>日期</th><th>变更内容</th><th>作者</th></tr></thead><tbody><tr><td>v0.1.0</td><td>YYYY-MM-DD</td><td>初稿创建</td><td>[姓名]</td></tr></tbody></table>',70)])])}const c=a(e,[["render",l]]);export{u as __pageData,c as default};
